package com.cpf.starter.notification;import java.time.Instant;public record CpfNotificationResult(String notificationId,String provider,String status,String providerMessageId,String detail,Instant processedAt){public static CpfNotificationResult sent(String id,String provider,String providerId){return new CpfNotificationResult(id,provider,"SENT",providerId,null,Instant.now());}public static CpfNotificationResult unknown(String id,String provider,String detail){return new CpfNotificationResult(id,provider,"UNKNOWN_RESULT",null,detail,Instant.now());}}
